Here’s a quick, self‑contained demo of the React Context API that you can paste into a file like `App.js` in a Create‑React‑App project (or any React setup). It shows how to create a context, provide a value, and consume it in nested components.

```jsx
import React, { createContext, useContext, useState } from 'react';

// 1. Create a context
const ThemeContext = createContext();

// 2. A provider component that holds the state
const ThemeProvider = ({ children }) => {
  const [theme, setTheme] = useState('light');

  const toggleTheme = () => {
    setTheme(prev => (prev === 'light' ? 'dark' : 'light'));
  };

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

// 3. A component that consumes the context
const ThemedButton = () => {
  const { theme, toggleTheme } = useContext(ThemeContext);

  return (
    <button
      onClick={toggleTheme}
      style={{
        background: theme === 'light' ? '#eee' : '#333',
        color: theme === 'light' ? '#333' : '#eee',
        padding: '10px 20px',
        border: 'none',
        borderRadius: '4px',
      }}
    >
      Current theme: {theme}
    </button>
  );
};

// 4. Main app
const App = () => {
  return (
    <ThemeProvider>
      <div style={{ padding: '20px' }}>
        <h1>React Context API Demo</h1>
        <ThemedButton />
      </div>
    </ThemeProvider>
  );
};

export default App;
```

